#pragma once

#include "camel/execute/pass/runtime_trans.h"

namespace ctx = camel::core::context;

/**
 * JitAsmDumpPass: attempts to JIT-compile every graph and prints assembly
 * instructions generated by the encoder during encoding.
 */
class JitAsmDumpPass : public RuntimeGraphTranslatePass {
  public:
    JitAsmDumpPass(const ctx::context_ptr_t &ctx) : RuntimeGraphTranslatePass(ctx) {}
    virtual ~JitAsmDumpPass() = default;

    virtual const camel::runtime::Program *
    apply(const camel::runtime::Program *program, std::ostream &os) override;
};
